<?php

namespace App\Modules\Identity\Domain\Sessions;

/**
 * What a phone says about itself when it signs in (FR-020). The session id is
 * generated by the client (P-06 rule 2), which is what makes a retried
 * sign-in rotate the same session instead of creating a second one.
 */
final readonly class DeviceDescription
{
    public function __construct(
        public string $sessionId,
        public string $deviceId,
        public string $name,
        public string $platform,
        public string $appVersion,
    ) {}
}
